/bin/bash -c "python3 - <<'PY'
from pypdf import PdfReader
r=PdfReader('manuscript.pdf')
links=[]
for i,p in enumerate(r.pages,1):
    for ref in p.get('/Annots',[]):
        a=ref.get_object().get('/A')
        if a:
            a=a.get_object()
            if '/URI' in a:
                uri=str(a['/URI'])
                if not ('doi.org' in uri or 'arxiv.org' in uri or 'aclanthology.org' in uri):
                    links.append((i,uri))
print('Non-DOI/arXiv/ACL external links:',links)
PY"
